<script setup lang="ts">
import { computed, ref, watch } from "vue"
import { useMutation, useQuery, useQueryClient } from "@tanstack/vue-query"
import { ApiError } from "../../api/client"
import OperationModal from "../../shared/components/OperationModal.vue"
import { currentUserQueryOptions } from "../auth/auth"
import { getBrief, getMasterContent, getPlatformContent } from "../content/api"
import { getPublishTask, getPublishTaskPage, listPublishTasks } from "../publishing/api"
import { analyticsKeys,createShortLink,createTrackingLink,getChannelSummary,getChannelSummaryPage,getShortPage,getTrackingPage,listShortLinks,listTrackingLinks } from "./api"

const iso=(date:Date)=>date.toISOString().slice(0,10)
const today=new Date(),startDefault=new Date(today.getTime()-29*86400000)
const start=ref(iso(startDefault)),end=ref(iso(today)),campaign=ref(""),platform=ref(""),product=ref(""),country=ref("")
const summaryUrl=ref<string|null>(null),trackingUrl=ref<string|null>(null),shortUrl=ref<string|null>(null),publishedUrl=ref<string|null>(null)
const message=ref(""),client=useQueryClient(),user=useQuery(currentUserQueryOptions()),createOpen=ref(false),taskId=ref(""),productId=ref(""),utmSource=ref(""),utmMedium=ref("social"),utmCampaign=ref("")
const org=computed(()=>user.data.value?.organization.id??"")
const permissions=computed(()=>user.data.value?.membership.permissions??[])
const canRead=computed(()=>permissions.value.includes("tracking.read"))
const canManage=computed(()=>permissions.value.includes("tracking.manage"))
const filters=computed(()=>({start:start.value,end:end.value,campaign:campaign.value,platform:platform.value,product:product.value,country:country.value.toUpperCase(),limit:"20",offset:"0"}))
const enabled=computed(()=>Boolean(org.value)&&canRead.value)
const summary=useQuery({queryKey:computed(()=>[...analyticsKeys.summary(org.value,filters.value),summaryUrl.value]),queryFn:()=>summaryUrl.value?getChannelSummaryPage(summaryUrl.value):getChannelSummary(filters.value),enabled})
const tracking=useQuery({queryKey:computed(()=>[...analyticsKeys.tracking(org.value),trackingUrl.value]),queryFn:()=>trackingUrl.value?getTrackingPage(trackingUrl.value):listTrackingLinks(),enabled})
const shorts=useQuery({queryKey:computed(()=>[...analyticsKeys.short(org.value),shortUrl.value]),queryFn:()=>shortUrl.value?getShortPage(shortUrl.value):listShortLinks(),enabled})
const published=useQuery({queryKey:computed(()=>[...analyticsKeys.all(org.value),"published",publishedUrl.value]),queryFn:()=>publishedUrl.value?getPublishTaskPage(publishedUrl.value):listPublishTasks(),enabled:computed(()=>enabled.value&&canManage.value)})
const publishedTasks=computed(()=>published.data.value?.results.filter(task=>Boolean(task.published_post))??[])

async function loadProvenance(id:string){
  const task=await getPublishTask(id)
  if(!task.published_post)throw new ApiError(0,"请选择已发布的内容。")
  const platformContent=await getPlatformContent(task.platform_content_id)
  const master=await getMasterContent(platformContent.master_content_id)
  const brief=await getBrief(master.brief_id)
  if(!brief.product_ids.length||!brief.landing_page_url)throw new ApiError(0,"内容来源缺少产品或落地页，无法创建追踪链接。")
  return {task,brief,productIds:brief.product_ids}
}
const provenance=useQuery({queryKey:computed(()=>[...analyticsKeys.all(org.value),"provenance",taskId.value]),queryFn:()=>loadProvenance(taskId.value),enabled:computed(()=>enabled.value&&canManage.value&&Boolean(taskId.value))})
watch(()=>provenance.data.value?.productIds,(ids)=>{productId.value=ids?.length===1?ids[0]:""})
const short=useMutation({mutationFn:(id:string)=>{if(!canManage.value)throw new ApiError(403,"没有管理追踪链接的权限。");return createShortLink(id,crypto.randomUUID())},onSuccess:async()=>{message.value="短链接已创建。";await client.invalidateQueries({queryKey:analyticsKeys.short(org.value)})}})
const create=useMutation({mutationFn:async()=>{if(!canManage.value)throw new ApiError(403,"没有创建追踪链接的权限。");const fresh=await loadProvenance(taskId.value);if(!fresh.productIds.includes(productId.value))throw new ApiError(0,"所选产品不属于当前内容来源，请重新选择。");return createTrackingLink({destination:fresh.brief.landing_page_url,utm_source:utmSource.value,utm_medium:utmMedium.value,utm_campaign:utmCampaign.value,campaign_id:fresh.brief.campaign_id,platform_id:fresh.task.platform_id,product_id:productId.value,published_post_id:fresh.task.published_post!.id},crypto.randomUUID())},onSuccess:async()=>{closeCreate();message.value="追踪链接已创建。";await client.invalidateQueries({queryKey:analyticsKeys.tracking(org.value)})}})
const maxClicks=computed(()=>Math.max(1,...(summary.data.value?.results.map(row=>row.clicks)??[1])))
const err=(value:unknown)=>value instanceof ApiError?value.userMessage:"分析数据暂时无法加载，请稍后重试。"
async function copy(value:string){try{await navigator.clipboard.writeText(value);message.value="已复制链接。"}catch{message.value="复制失败，请手动选择链接。"}}
function reset(){start.value=iso(startDefault);end.value=iso(today);campaign.value="";platform.value="";product.value="";country.value=""}
function closeCreate(){createOpen.value=false;taskId.value="";productId.value="";utmSource.value="";utmMedium.value="social";utmCampaign.value=""}
watch([start,end,campaign,platform,product,country],()=>{summaryUrl.value=null})
watch(org,()=>{summaryUrl.value=null;trackingUrl.value=null;shortUrl.value=null;publishedUrl.value=null;closeCreate()})
</script>

<template><main class="page-stack"><header class="link-row"><div><p class="eyebrow">渠道成效</p><h1>数据看板</h1><p>查看聚合点击趋势，并管理已发布内容的追踪链接。</p></div><button v-if="canManage" class="primary-action" @click="createOpen=true">创建追踪链接</button></header><section v-if="!canRead" class="panel" role="alert"><h2>没有分析权限</h2><p>需要 tracking.read 权限才能查看此页面。</p></section><template v-else><p v-if="message" role="status">{{ message }}</p><section class="filters" aria-label="分析筛选"><label>开始日期<input v-model="start" type="date"></label><label>结束日期<input v-model="end" type="date"></label><label>活动<input v-model="campaign"></label><label>平台<input v-model="platform"></label><label>产品<input v-model="product"></label><label>国家代码<input v-model="country" maxlength="2" placeholder="DE"></label><button @click="reset">恢复近 30 天</button></section><p v-if="summary.isPending.value" role="status">正在加载分析数据…</p><section v-else-if="summary.isError.value" class="panel" role="alert"><h2>分析数据没有加载成功</h2><p>{{ err(summary.error.value) }}</p><button @click="summary.refetch()">重新加载分析数据</button></section><template v-else><section class="metric panel" aria-label="总点击数" aria-live="polite"><span>总点击数</span><strong>{{ summary.data.value?.total_clicks??0 }}</strong><small>符合当前筛选条件</small></section><section v-if="summary.data.value?.results.length" class="panel"><h2>点击趋势</h2><div class="bars" aria-label="点击趋势图"><div v-for="row in summary.data.value.results" :key="`${row.date}-${row.platform_id}-${row.country}`" class="bar-row"><span>{{ row.date }}</span><span class="bar" :style="{width:`${Math.max(4,row.clicks/maxClicks*100)}%`}"></span><strong>{{ row.clicks }}</strong></div></div><div class="table-wrap"><table aria-label="渠道点击明细"><thead><tr><th>日期</th><th>国家</th><th>渠道</th><th>产品</th><th>点击</th></tr></thead><tbody><tr v-for="row in summary.data.value.results" :key="`${row.date}-${row.campaign_id}-${row.product_id}`"><td>{{ row.date }}</td><td>{{ row.country||'未知' }}</td><td>{{ row.platform_id }}</td><td>{{ row.product_id }}</td><td>{{ row.clicks }}</td></tr></tbody></table></div></section><section v-else class="panel"><h2>当前条件暂无点击</h2><p>尝试扩大日期范围或清除筛选。</p></section><nav class="actions" aria-label="分析结果分页"><button :disabled="!summary.data.value?.previous" @click="summaryUrl=summary.data.value?.previous??null">上一页</button><button :disabled="!summary.data.value?.next" @click="summaryUrl=summary.data.value?.next??null">下一页</button></nav></template><section class="panel"><h2>追踪链接</h2><p v-if="tracking.isError.value" role="alert">{{ err(tracking.error.value) }} <button @click="tracking.refetch()">重新加载链接</button></p><p v-else-if="!tracking.data.value?.results.length">暂无追踪链接。</p><article v-for="link in tracking.data.value?.results" :key="link.id" class="link-row"><div><strong>{{ link.utm_campaign }}</strong><p>{{ link.full_url }}</p></div><div class="actions"><button @click="copy(link.full_url)">复制</button><button v-if="canManage" @click="short.mutate(link.id)">创建短链接</button></div></article><nav class="actions" aria-label="追踪链接分页"><button :disabled="!tracking.data.value?.previous" @click="trackingUrl=tracking.data.value?.previous??null">上一页</button><button :disabled="!tracking.data.value?.next" @click="trackingUrl=tracking.data.value?.next??null">下一页</button></nav></section><section class="panel"><h2>短链接</h2><p v-if="shorts.isError.value" role="alert">{{ err(shorts.error.value) }}</p><article v-for="item in shorts.data.value?.results" :key="item.id" class="link-row"><code>{{ item.redirect_path }}</code><button @click="copy(item.redirect_path)">复制</button></article><nav class="actions" aria-label="短链接分页"><button :disabled="!shorts.data.value?.previous" @click="shortUrl=shorts.data.value?.previous??null">上一页</button><button :disabled="!shorts.data.value?.next" @click="shortUrl=shorts.data.value?.next??null">下一页</button></nav></section><section v-if="canManage" class="panel"><h2>已发布内容</h2><p v-for="task in publishedTasks" :key="task.id">{{ task.published_post?.external_id||task.id }}</p><nav class="actions" aria-label="已发布内容分页"><button :disabled="!published.data.value?.previous" @click="publishedUrl=published.data.value?.previous??null">上一页</button><button :disabled="!published.data.value?.next" @click="publishedUrl=published.data.value?.next??null">下一页</button></nav></section><OperationModal v-if="createOpen" title="创建追踪链接" title-id="tracking-title" @close="closeCreate"><form class="modal" @submit.prevent="create.mutate()"><label>已发布内容<select v-model="taskId" required><option value="" disabled>请选择</option><option v-for="task in publishedTasks" :key="task.id" :value="task.id">{{ task.published_post?.external_id||task.id }}</option></select></label><label v-if="(provenance.data.value?.productIds.length??0)>1">产品<select v-model="productId" required><option value="" disabled>请选择</option><option v-for="id in provenance.data.value?.productIds" :key="id" :value="id">{{ id }}</option></select></label><p v-else-if="provenance.data.value?.productIds.length===1">产品：{{ provenance.data.value.productIds[0] }}</p><label>来源<input v-model="utmSource" required placeholder="linkedin"></label><label>媒介<input v-model="utmMedium" required></label><label>活动标识<input v-model="utmCampaign" required></label><p>目标地址、活动、平台、产品与发布记录会从当前内容来源锁定，并在提交时复验。</p><p v-if="provenance.isError.value||create.isError.value" role="alert">{{ err(provenance.error.value||create.error.value) }}</p><div class="actions"><button type="button" @click="closeCreate">取消</button><button class="primary-action" :disabled="create.isPending.value||provenance.isPending.value||!productId">创建</button></div></form></OperationModal></template></main></template>
<style scoped>.filters{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem;align-items:end}.filters label,.modal label{display:grid;gap:.35rem}.panel,.filters{padding:1.1rem;border:1px solid var(--border-color,#d8dee8);border-radius:1rem;background:white}.metric{display:grid;gap:.25rem}.metric strong{font-size:2.5rem;color:#005ba8}.bars{display:grid;gap:.5rem}.bar-row{display:grid;grid-template-columns:7rem minmax(2rem,1fr) 3rem;gap:.5rem;align-items:center}.bar{height:.8rem;background:#005ba8;border-radius:999px}.table-wrap{overflow-x:auto;margin-top:1rem}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:.65rem;border-bottom:1px solid #e5e9ef}.link-row,.actions{display:flex;justify-content:space-between;align-items:center;gap:1rem}.link-row p{overflow-wrap:anywhere}.actions{justify-content:flex-end}.modal{display:grid;gap:1rem}@media(max-width:700px){.filters{grid-template-columns:1fr}.link-row{display:grid}.bar-row{grid-template-columns:6rem 1fr 2rem}}</style>
